update public.bookings set status = 'booked', want_date = current_date + 4, want_dates = array[current_date + 4], due_date = current_date + 10 where id = 'c00d3678-3f68-5aa4-8e27-c295130b7d0e';

select b.id, 'proof',
       'Done: ' || case when s.category in ('radio', 'tv', 'dj') then 'played' else 'posted' end
              || case when b.plays > 1 then ' ' || b.plays || ' times' else '' end
              || case when b.status = 'proof_submitted' then '. Please check and approve 🙏' else '. Thank you!' end,
       b.proof_at
from public.bookings b join public.sellers s on s.id = b.seller_id
where s.is_example and b.proof_at is not null and not exists (select 1 from public.proofs p where p.booking_id = b.id);

update public.campaigns c set completed_at = x.t from (select campaign_id, max(paid_out_at) t from public.bookings group by campaign_id) x where x.campaign_id = c.id and c.status = 'completed' and c.artist_id in (select id from public.profiles where is_example);

select (select count(*) from public.sellers where is_example) as example_promoters, (select count(*) from public.profiles where is_example) as example_artists, (select count(*) from public.campaigns c join public.profiles p on p.id = c.artist_id where p.is_example) as example_songs, (select count(*) from public.bookings b join public.sellers s on s.id = b.seller_id where s.is_example) as example_bookings;
